package com.huy.enterprise.inventory;
import com.huy.enterprise.common.*; import com.huy.enterprise.product.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.time.OffsetDateTime; import java.util.*;
@Service @RequiredArgsConstructor @Transactional(readOnly=true) public class InventoryService{private final InventoryItemRepository repository;private final WarehouseRepository warehouses;private final ProductRepository products;public List<InventoryResponse> all(){return repository.findAll().stream().map(InventoryResponse::from).toList();}public InventoryResponse one(UUID id){return InventoryResponse.from(get(id));}public List<InventoryResponse> lowStock(){return repository.findLowStockItems().stream().map(InventoryResponse::from).toList();}
@Transactional public InventoryResponse create(InventoryRequest r){if(repository.existsByWarehouseIdAndProductId(r.warehouseId(),r.productId()))throw new ConflictException("Inventory item already exists for warehouse and product");InventoryItem i=new InventoryItem();apply(i,r);return InventoryResponse.from(repository.save(i));}@Transactional public InventoryResponse update(UUID id,InventoryRequest r){InventoryItem i=get(id);if((!i.getWarehouse().getId().equals(r.warehouseId())||!i.getProduct().getId().equals(r.productId()))&&repository.existsByWarehouseIdAndProductId(r.warehouseId(),r.productId()))throw new ConflictException("Inventory item already exists for warehouse and product");apply(i,r);return InventoryResponse.from(repository.save(i));}
private InventoryItem get(UUID id){return repository.findById(id).orElseThrow(()->new ResourceNotFoundException("Inventory item not found: "+id));}private void apply(InventoryItem i,InventoryRequest r){i.setWarehouse(warehouses.findById(r.warehouseId()).orElseThrow(()->new ResourceNotFoundException("Warehouse not found: "+r.warehouseId())));i.setProduct(products.findById(r.productId()).orElseThrow(()->new ResourceNotFoundException("Product not found: "+r.productId())));i.setQuantity(r.quantity());i.setLowStockThreshold(r.lowStockThreshold());i.setLastUpdated(OffsetDateTime.now());}}
